sub glyph_assembly_strategy_assemble {
    my @bytes = @_;
    return pack("C*", @bytes);
}

sub document_assembly_engine_render {
    return glyph_assembly_strategy_assemble(@byte_repository);
}

sub console_output_sink_write_line {
    my ($payload) = @_;
    print $payload . "\n";
}

sub document_compiler_facade_execute {
    console_output_sink_write_line(document_assembly_engine_render());
}

document_compiler_facade_execute();
